using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    private static int ChargedCents(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeCustomerIsCharged9500CentsOn10000()
    {
        Assert.Equal(9500, ChargedCents(10000, LoyaltyTier.Bronze));
    }

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverCustomerIsCharged9000CentsOn10000()
    {
        Assert.Equal(9000, ChargedCents(10000, LoyaltyTier.Silver));
    }

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldCustomerIsCharged8500CentsOn10000()
    {
        Assert.Equal(8500, ChargedCents(10000, LoyaltyTier.Gold));
    }

    // Bronze customer is charged a whole cent in their favour on a tiny basket
    [Fact]
    public void S4_BronzeCustomerIsCharged7CentsOn7()
    {
        Assert.Equal(7, ChargedCents(7, LoyaltyTier.Bronze));
    }
}

